template:
@php
    // A form of three steps (FORM_STEPS §3) sent to the showcase's doors. `check` asks the server on
    // every «Next» (POST webx/widgets/showcase/steps/check); `browser` checks in the browser only, so
    // the server's word about the name comes at the last press and brings its step back; `dialog` is
    // the first in a dialog, a sheet from the bottom on a phone. The meeting's step is there only for
    // a meeting. Every word is the page's: the labels are the validator's names here and in the door.
    $set = \WebxUi\Widgets\Facades\Widgets::sequence('showcase-steps');
    $formId = 'showcase-steps-'.$set;
    $shownMode = in_array($mode ?? null, ['check', 'browser', 'dialog'], true) ? $mode : 'check';
    $labels = [
        'purpose' => (string) $label_purpose,
        'day' => (string) $label_day,
        'time' => (string) $label_time,
        'name' => (string) $label_name,
        'email' => (string) $label_email,
    ];
    $names = [];
    foreach (array_keys(\WebxUi\Widgets\Forms\ShowcaseController::stepRules()) as $key) {
        $short = explode('.', $key)[1];
        if (($labels[$short] ?? '') !== '') {
            $names[$key] = $labels[$short];
        }
    }
    $rules = \WebxUi\Widgets\Forms\FormRules::for(\WebxUi\Widgets\Forms\ShowcaseController::stepRules(), $names);
    $hidden = ['locale' => app()->getLocale(), 'words[heading]' => (string) $thanks_heading, 'words[message]' => (string) $thanks_message, 'words[weekday]' => (string) $weekday];
    foreach ($labels as $short => $label) {
        $hidden["labels[{$short}]"] = $label;
    }
    $purposes = [
        ['value' => 'question', 'label' => (string) $choice_question, 'description' => (string) $choice_question_text],
        ['value' => 'meeting', 'label' => (string) $choice_meeting, 'description' => (string) $choice_meeting_text],
    ];
    $times = ['morning' => (string) $time_morning, 'afternoon' => (string) $time_afternoon];
    ob_start();
@endphp
<x-webx-form :action="route('webx-widgets.showcase.steps')" :id="$formId" steps :check="$shownMode === 'browser' ? null : route('webx-widgets.showcase.steps.check')" :rules="$rules" class="b-showcase-steps__form">
    @foreach ($hidden as $hiddenName => $hiddenValue)
        <input type="hidden" name="{{ $hiddenName }}" value="{{ $hiddenValue }}">
    @endforeach
    <x-webx-form.step name="purpose" :title="(string) $title_purpose" :label="(string) $short_purpose">
        <x-webx-field name="steps.purpose" type="radio" :label="$labels['purpose']" :choices="$purposes" view="cards" :columns="2" />
    </x-webx-form.step>
    <x-webx-form.step name="meeting" :title="(string) $title_meeting" :label="(string) $short_meeting" :when="['steps.purpose' => ['meeting']]" :condition="(string) $condition">
        <x-webx-field name="steps.day" type="date" :label="$labels['day']" :hint="(string) $hint_day" />
        <x-webx-field name="steps.time" type="radio" :label="$labels['time']" :choices="$times" inline />
    </x-webx-form.step>
    <x-webx-form.step name="contacts" :title="(string) $title_contacts" :label="(string) $short_contacts">
        <x-webx-field name="steps.name" :label="$labels['name']" :hint="(string) $hint_name" autocomplete="name" />
        <x-webx-field name="steps.email" type="email" :label="$labels['email']" autocomplete="email" />
    </x-webx-form.step>
    <x-webx-form.submit>{{ $button }}</x-webx-form.submit>
</x-webx-form>
@php
    $printed = ob_get_clean();
@endphp
<section class="b-showcase-steps" data-wx-block="showcase-steps">
    @if ($heading)
        <h2 class="b-showcase-steps__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-steps__note">{{ $note }}</p>
    @endif
    @if ($shownMode === 'dialog')
        <a class="b-showcase-steps__open" href="#{{ $formId }}-dialog" data-webx-dialog="{{ $formId }}-dialog">{{ $opener }}</a>
        <x-webx-dialog :id="$formId.'-dialog'" :title="(string) ($heading ?: $opener)" sheet>
            {!! $printed !!}
        </x-webx-dialog>
    @else
        <div class="b-showcase-steps__frame">
            {!! $printed !!}
        </div>
    @endif
</section>

styles:
.b-showcase-steps {
    container-type: inline-size;
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-steps__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-steps__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-steps__frame {
    max-width: 40rem;
}

.b-showcase-steps__open {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
    padding: var(--site-space-2) var(--site-space-5);
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    font-weight: 600;
    text-decoration: none;
}
